    q: "How much sleep does a cat actually need?",
    a: "Adult cats sleep 12–16 hours a day on average, while kittens and senior cats can sleep up to 20 hours. As crepuscular hunters, cats are most active around dawn and dusk and conserve energy the rest of the time.",
  },
  {
    q: "Is it safe to give my cat milk?",
    a: "Most adult cats are lactose intolerant, so cow's milk can cause stomach upset and diarrhea. Fresh water is always best. If you'd like to offer a treat, look for lactose-free cat milk made specifically for felines.",
  },
  {
    q: "Why does my cat knead with their paws?",
    a: "Kneading — sometimes called \"making biscuits\" — is a behavior kittens use to stimulate milk flow while nursing. Adult cats keep doing it as a sign of comfort, contentment, and bonding with you or a soft surface.",
  },
  {
    q: "Do cats really have nine lives?",
    a: "It's a myth, of course — cats have one life like every other animal. The legend likely comes from their remarkable agility, righting reflex, and ability to survive surprising falls. Indoor cats typically live 13–17 years with good care.",
  },
  {
    q: "How can I tell if my cat is happy?",
    a: "Look for slow blinks, a relaxed posture, a softly upright tail, gentle purring, and a healthy appetite. Happy cats also play, groom themselves regularly, and choose to spend time near the people they trust.",
  },
];

function FaqItem({ question, answer }) {
  const [open, setOpen] = useState(false);
  const panelId = useId();

  return (
    <div className="example">
      <h3>
        <button
          type="button"
          className="faq-trigger"
          aria-expanded={open}
          aria-controls={panelId}
          onClick={() => setOpen((v) => !v)}
        >
          <span>{question}</span>
          <svg
            className="faq-icon"
            viewBox="0 0 20 20"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden="true"
            focusable="false"
          >
            <polyline points="5 8 10 13 15 8" />
          </svg>
        </button>
      </h3>
      <div id={panelId} className="details" hidden={!open}>
        <p>{answer}</p>
      </div>
    </div>
  );
}

function FaqList({ items }) {
  return (
    <div className="faq-list">
      {items.map((item, i) => (
        <FaqItem key={i} question={item.q} answer={item.a} />
      ))}
    </div>
  );
}

function App() {
  return (
    <div className="page">
      <header className="hero">
        <span className="eyebrow">Cat FAQ</span>
        <h1>Everything you wanted to know about cats</h1>
        <p>
          Curious about your feline companion? Tap a question below to reveal
          the answer. No question is too small — we love cats too.
        </p>
      </header>
      <main id="main">
        <FaqList items={FAQS} />
      </main>
      <footer>
        <p>Made with care for cat people everywhere. 🐾</p>
      </footer>
    </div>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(
  <StrictMode>
    <App />
  </StrictMode>
);

