* { box-sizing: border-box; }

html, body { margin: 0; padding: 0; }

body {
  background: var(--bg);
  color: var(--text);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--text);
  color: #fff;
  padding: 0.75rem 1rem;
  border-radius: 0 0 8px 0;
  z-index: 100;
  text-decoration: none;
}
.skip-link:focus {
  left: 0;
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.page {
  max-width: 720px;
  margin: 0 auto;
  padding: 3rem 1.25rem 4rem;
}

.hero {
  text-align: center;
  margin-bottom: 2.5rem;
}

.hero .eyebrow {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
  background: rgba(79, 70, 229, 0.08);
  padding: 0.35rem 0.75rem;
  border-radius: 999px;
  margin-bottom: 1rem;
}

.hero h1 {
  font-size: clamp(2rem, 5vw, 2.75rem);
  line-height: 1.15;
  margin: 0 0 0.75rem;
  letter-spacing: -0.02em;
}

.hero p {
  color: var(--muted);
  font-size: 1.0625rem;
  max-width: 38rem;
  margin: 0 auto;
}

.faq-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: border-color 0.15s ease;
}

.example:hover { border-color: #d3d3cd; }

.example h3 { margin: 0; }

.faq-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  background: transparent;
  border: 0;
  padding: 1.125rem 1.25rem;
  text-align: left;
  font: inherit;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  border-radius: var(--radius);
}

.faq-trigger:hover { background: #fafaf8; }

.faq-trigger:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}

.faq-icon {
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  color: var(--muted);
  transition: transform 0.2s ease;
}

.faq-trigger[aria-expanded="true"] .faq-icon {
  transform: rotate(180deg);
  color: var(--accent);
}

.details {
  padding: 0 1.25rem 1.25rem;
  color: var(--muted);
  border-top: 1px solid var(--border);
}

.details p { margin: 1rem 0 0; }

footer {
  margin-top: 3rem;
  text-align: center;
  color: var(--muted);
  font-size: 0.875rem;
}

@media (prefers-reduced-motion: reduce) {
  .faq-icon { transition: none; }
}

@media (forced-colors: active) {
  .example { border: 1px solid CanvasText; }
