  // Also test with one panel expanded
  await page.click('.faq-trigger');
  await page.waitForTimeout(100);
  let r2 = await page.evaluate(async () => await window.axe.run());
  await browser.close();

  const summarize = (rr) => ({
    wcag: rr.violations.filter(v => !v.tags.includes('best-practice')).map(v => ({id: v.id, impact: v.impact, targets: v.nodes.map(n=>n.target)})),
    bp: rr.violations.filter(v => v.tags.includes('best-practice')).map(v => ({id: v.id, targets: v.nodes.map(n=>n.target)})),
